"""Read-only equivalence proof for a single roster actor placement correction."""
import bpy,json,hashlib,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];BEFORE=Path(sys.argv[sys.argv.index('--')+1]);AFTER=ROOT/'Blender/Characters.blend';OUT=ROOT/'Validation/roster_translation_independent.json'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def matrix(m):return [[float(v) for v in row] for row in m]
def digest(x):return hashlib.sha256(json.dumps(x,sort_keys=True,separators=(',',':')).encode()).hexdigest()
def read(path):
 bpy.ops.wm.open_mainfile(filepath=str(path),use_scripts=False);bpy.context.view_layer.update();out={}
 for rig in [o for o in bpy.context.scene.objects if o.type=='ARMATURE']:
  payload={'rotation':list(rig.rotation_euler),'scale':list(rig.scale),'bones':{b.name:{'head':list(b.head_local),'tail':list(b.tail_local),'matrix':matrix(b.matrix_local),'parent':b.parent.name if b.parent else None} for b in rig.data.bones},'pose':{b.name:matrix(b.matrix_basis) for b in rig.pose.bones},'children':{}}
  for obj in rig.children_recursive:
   d={'type':obj.type,'matrix_basis':matrix(obj.matrix_basis),'matrix_parent_inverse':matrix(obj.matrix_parent_inverse),'parent_type':obj.parent_type,'parent_bone':obj.parent_bone,'parent':obj.parent.name}
   if obj.type=='MESH':
    d.update(vertices=[(list(v.co),sorted((obj.vertex_groups[g.group].name,g.weight) for g in v.groups)) for v in obj.data.vertices],faces=[(list(p.vertices),p.material_index,p.use_smooth) for p in obj.data.polygons],materials=[m.name for m in obj.data.materials])
   payload['children'][obj.name]=d
  out[rig.name]={'location':list(rig.location),'invariant_sha256':digest(payload),'children':len(payload['children']),'bones':len(rig.data.bones)}
 return out
old=read(BEFORE);new=read(AFTER);rows=[]
for name,data in old.items():
 assert data['invariant_sha256']==new[name]['invariant_sha256'],(name,'meaningful local change')
 delta=[b-a for a,b in zip(data['location'],new[name]['location'])]
 if name=='Patrol_Officer_Rig':assert abs(new[name]['location'][0]-1.55)<1e-6 and abs(delta[1])+abs(delta[2])<1e-6
 else:assert max(abs(v) for v in delta)<1e-6,(name,'unexpectedtranslation')
 rows.append({'rig':name,'local_geometry_skin_skeleton_pose_anchor_transform_match':True,'invariant_sha256':data['invariant_sha256'],'world_translation_before_m':data['location'],'world_translation_after_m':new[name]['location'],'translation_delta_m':delta})
report={'status':'PASS','scope':'Every base character mesh coordinate,vertex skinweight,polygon index/material/smoothing,object-local transform,parent inverse,bone hierarchy/restmatrix,pose and child anchor transform exactly matches before/after. Only patrol root roster placement changes; animation/FBX files are not regenerated by this correction.','before_base_sha256':sha(BEFORE),'source_sha256':{'Blender/Characters.blend':sha(AFTER)},'rigs':rows}
OUT.write_text(json.dumps(report,indent=2));print(json.dumps(report,indent=2))
